// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 _value, bytes calldata _data) public {
        Reverter reverter = new Reverter();
        vm.deal(address(c), _value);
        vm.startPrank(c.owner());
        bool reverted;
        try c.sendMoney(address(reverter), _value, _data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        vm.stopPrank();
        assertTrue(reverted);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
